public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // check if the starting and ending coordinates are within the n-teresting space
  if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n ||
      end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
    return "cannot be travelled";
  }

  // create a 2D array to represent the n-teresting space
  boolean[][] visited = new boolean[n][n];

  // initialize the starting n-tersection as visited
  visited[start[0]][start[1]] = true;

  // perform a depth-first search to find the ending n-tersection
  if (dfs(visited, start, end, paths)) {
    return "can be travelled";
  } else {
    return "cannot be travelled";
  }
}

private static boolean dfs(boolean[][] visited, int[] current, int[] end, int[][] paths) {
  // if the current n-tersection is the ending n-tersection, return true
  if (current[0] == end[0] && current[1] == end[1]) {
    return true;
  }

  // for each neighbor of the current n-tersection
  for (int[] neighbor : paths[current[0]][current[1]]) {
    // if the neighbor has not been visited, mark it as visited and recursively search its neighbors
    if (!visited[neighbor[0]][neighbor[1]]) {
      visited[neighbor[0]][neighbor[1]] = true;
      if (dfs(visited, neighbor, end, paths)) {
        return true;
      }
    }
  }

  // if no path was found to the ending n-tersection, return false
  return false;
}

