public boolean hasAllCodes(String s, int k) {
    // Check if the length of s is greater than or equal to k
    if (s.length() < k) {
        return false;
    }

    // Initialize a set to store all binary strings of length k
    Set<String> binaryStrings = new HashSet<>();

    // Iterate over the length of s and check if every binary string of length k is a substring of s
    for (int i = 0; i <= s.length() - k; i++) {
        String binaryString = s.substring(i, i + k);
        if (!binaryStrings.contains(binaryString)) {
            return false;
        }
        binaryStrings.add(binaryString);
    }

    return true;
}

