public int minInsertions(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    int openBrackets = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            stack.push(c);
            openBrackets++;
        } else if (c == ')') {
            if (openBrackets == 0) {
                stack.push(c);
            } else {
                stack.pop();
                openBrackets--;
            }
        }
    }
    return openBrackets;
}

public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = 2 * i + 1;
    }
    int minOperations = 0;
    for (int i = 1; i < n; i++) {
        int diff = Math.abs(arr[i] - arr[i - 1]);
        if (diff > 0) {
            int x = i, y = i - 1;
            if (arr[x] > arr[y]) {
                x = i - 1;
                y = i;
            }
            arr[x] -= 1;
            arr[y] += 1;
            minOperations++;
        }
    }
    return minOperations;
}

