public int findMinFibonacciNumbers(int k) {
    // Initialize the Fibonacci sequence
    int[] fibonacci = new int[k + 1];
    fibonacci[0] = 1;
    fibonacci[1] = 1;

    // Calculate the Fibonacci numbers up to k
    for (int i = 2; i <= k; i++) {
        fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
    }

    // Find the minimum number of Fibonacci numbers whose sum is equal to k
    int minNumber = Integer.MAX_VALUE;
    for (int i = 0; i <= k; i++) {
        if (fibonacci[i] == k) {
            minNumber = 1;
            break;
        } else if (fibonacci[i] > k) {
            break;
        }
        for (int j = i + 1; j <= k; j++) {
            if (fibonacci[i] + fibonacci[j] == k) {
                minNumber = Math.min(minNumber, 2);
                break;
            }
        }
    }

    return minNumber;
}

