public String getSmallestString(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("n and k must be positive.");
    }
    if (n < k) {
        throw new IllegalArgumentException("k must not be greater than n.");
    }
    StringBuilder sb = new StringBuilder();
    int remaining = k;
    for (int i = 1; i <= n; i++) {
        int charValue = (int) Math.ceil(remaining / Math.pow(26, i));
        if (charValue == 0) {
            break;
        }
        sb.append((char) ('a' + charValue - 1));
        remaining -= charValue;
    }
    return sb.toString();
}

