public static List<Integer> findSteppingNumbers(int low, int high) {
    // Check inputs for validity
    if (low < 0 || high > 1000000000 || low > high) {
        throw new IllegalArgumentException("Invalid input range");
    }

    List<Integer> steppingNumbers = new ArrayList<>();

    // Iterate from low to high and check if each number is a stepping number
    for (int i = low; i <= high; i++) {
        if (isSteppingNumber(i)) {
            steppingNumbers.add(i);
        }
    }

    // Sort the stepping numbers in ascending order and return them
    Collections.sort(steppingNumbers);
    return steppingNumbers;
}

private static boolean isSteppingNumber(int n) {
    int prevDigit = n % 10;
    for (int i = 1; i < 10; i++) {
        int currentDigit = (n / (int) Math.pow(10, i)) % 10;
        if (currentDigit != prevDigit && Math.abs(currentDigit - prevDigit) != 1) {
            return false;
        }
        prevDigit = currentDigit;
    }
    return true;
}

