public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                int k = i - 1;
                while (k >= 0 && mat[k][j] == 1) {
                    currentLength++;
                    k--;
                }
                k = i + 1;
                while (k < m && mat[k][j] == 1) {
                    currentLength++;
                    k++;
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }

    return maxLength;
}

