}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        throw new IllegalArgumentException("The input array is empty or null.");
    }
    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
        int currentHeight = heights[i];
        int minHeight = currentHeight;
        for (int j = i+1; j < heights.length; j++) {
            int nextHeight = heights[j];
            if (nextHeight < minHeight) {
                minHeight = nextHeight;
            }
        }
        maxArea = Math.max(maxArea, minHeight * (i+1));
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] diagonalOrder = new int[rows * cols];
    int index = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            diagonalOrder[index++] = mat[i][j];
        }
    }

    for (int i = 0; i < rows - 1; i++) {
        for (int j = cols - 2; j >= 0; j--) {
            diagonalOrder[index++] = mat[i][j];
        }
    }

    for (int i = 1; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            diagonalOrder[index++] = mat[i][j];
        }
    }

    return diagonalOrder;
}

public static int findSmallestInteger(int n) {
    // Convert the input integer to a character array
    char[] numChars = Integer.toString(n).toCharArray();

    // Sort the character array in ascending order
    Arrays.sort(numChars);

    // Build a new integer by concatenating the sorted characters
    int smallestInteger = Integer.parseInt(new String(numChars));

    // Check if the smallestInteger is greater than the input integer
    if (smallestInteger > n) {
        return smallestInteger;
    } else {
        return -1;
    }
}

