private static boolean isCenterSymmetric(String num) {
        int mid = num.length() / 2;
        for (int i = 0; i < mid; i++) {
            if (num.charAt(i) != num.charAt(num.length() - i - 1)) {
                return false;
            }
        }
        return true;
    }

public static boolean isBoomerang(int[][] points) {
    // Check if there are exactly 3 points
    if (points.length != 3) {
        return false;
    }

    // Get the slopes of the two lines between the points
    double slope1 = (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);
    double slope2 = (points[2][1] - points[1][1]) / (points[2][0] - points[1][0]);

    // Check if the slopes are equal
    if (slope1 == slope2) {
        return false;
    }

    // Check if the points are collinear
    if (points[0][0] * (points[1][1] - points[2][1]) + points[1][0] * (points[2][1] - points[0][1]) + points[2][0] * (points[0][1] - points[1][1]) == 0) {
        return false;
    }

    return true;
}

public static int findNthUglyNumber(int n) {
    /**
    * Find and return the nth ugly number.
    *
    * @param n The index of the ugly number to find.
    * @return The nth ugly number.
    *
    * Example:
    * findNthUglyNumber(10)
    * Output: 12
    */
    int uglyNumber = 0;
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    for (int i = 1; i < n; i++) {
        int currentUglyNumber = uglyNumbers[i - 1];
        currentUglyNumber *= 2;
        if (currentUglyNumber % 3 == 0) {
            currentUglyNumber /= 3;
        } else if (currentUglyNumber % 5 == 0) {
            currentUglyNumber /= 5;
        } else {
            currentUglyNumber *= 2;
        }
        uglyNumbers[i] = currentUglyNumber;
        uglyNumber = currentUglyNumber;
    }

    return uglyNumber;
}

public static int calculateEnergy(String s) {
  if (s.isEmpty()) {
    return 0;
  }
  int energy = 0;
  int count = 0;
  char current = s.charAt(0);
  for (int i = 0; i < s.length(); i++) {
    char c = s.charAt(i);
    if (c == current) {
      count++;
    } else {
      if (count > energy) {
        energy = count;
      }
      count = 1;
      current = c;
    }
  }
  if (count > energy) {
    energy = count;
  }
  return energy;
}

