public static int calculateUniqueSum(int[] nums) {
    // Handle edge case of empty array
    if (nums.length == 0) {
        return 0;
    }

    // Create a set to store unique elements
    Set<Integer> uniqueElements = new HashSet<>();

    // Iterate through the array and add unique elements to the set
    for (int num : nums) {
        if (!uniqueElements.contains(num)) {
            uniqueElements.add(num);
        }
    }

    // Calculate the sum of the unique elements
    int sum = 0;
    for (Integer element : uniqueElements) {
        sum += element;
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    int minCount = Integer.MAX_VALUE;
    for (int i = 1; i * i <= n; i++) {
        int count = 0;
        while (n > 0) {
            int sqrt = (int) Math.sqrt(n);
            count++;
            n -= sqrt * sqrt;
        }
        minCount = Math.min(minCount, count);
    }
    return minCount;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String reversed = "";
    for (String word : words) {
        StringBuilder sb = new StringBuilder(word);
        sb.reverse();
        reversed += sb.toString() + " ";
    }
    return reversed.trim();
}
